//! Input schema for the token-optimized YAML payload generated by an LLM.
//!
//! The LLM emits a flat, minimal YAML document. This module defines the
//! corresponding serde structs and provides a [`DiagramPayload::from_yaml`]
//! constructor that validates the input at the boundary.

use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

// ---------------------------------------------------------------------------
// Top-level diagram payload
// ---------------------------------------------------------------------------

/// Root structure of the token-optimized YAML payload produced by an LLM.
///
/// # Example
///
/// ```yaml
/// diagram_type: flowchart
/// theme: aws_light
/// nodes:
///   - id: n1
///     label: "API Gateway"
///     type: proxy
///   - id: n2
///     label: "User Database"
///     type: database
///     metadata: "Stores encrypted user credentials."
/// edges:
///   - from: n1
///     to: n2
///     label: "queries"
/// ```
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagramPayload {
    /// Optional human-readable title for the entire diagram.
    /// Rendered as a prominent title banner at the top of the canvas.
    #[serde(default, alias = "name")]
    pub title: Option<String>,

    /// Optional diagram description or subtitle.
    #[serde(default, alias = "subtitle", alias = "desc")]
    pub description: Option<String>,

    /// Logical diagram category (e.g. `flowchart`, `architecture`, `sequence`, `graph`).
    #[serde(default = "default_diagram_type", alias = "type", alias = "kind")]
    pub diagram_type: String,

    /// Visual theme: a built-in name (`light`, `dark`, `mono-light`, `mono-dark`,
    /// `classic`), or a mapping `{extends: <name>, …overrides}` — see `rdg --guide theming`.
    #[serde(default)]
    pub theme: Option<serde_yaml::Value>,

    /// Draw a legend of the node categories and edge styles used.
    #[serde(default)]
    pub legend: Option<bool>,

    /// Optional flow direction override: `tb` (top-to-bottom) or `lr` (left-to-right).
    /// Accepts aliases: `TB`, `LR`, `horizontal`, `vertical`.
    #[serde(default, alias = "flow", alias = "layout_direction")]
    pub direction: Option<String>,

    /// Optional vertical spacing between ranks in pixels.
    #[serde(default)]
    pub rank_spacing: Option<u32>,

    /// Optional horizontal spacing between sibling nodes in pixels.
    #[serde(default)]
    pub node_spacing: Option<u32>,

    /// Optional canvas-level configuration (margin, background).
    #[serde(default)]
    pub canvas: Option<CanvasConfig>,

    /// Optional spacing configuration, grouping the individual spacing knobs.
    /// `rank_spacing`/`node_spacing` above take priority over `spacing.rank`/`spacing.node`
    /// when both are set — they exist for backward compatibility with earlier payloads.
    #[serde(default)]
    pub spacing: Option<SpacingConfig>,

    /// When `true`, edges are annotated with a sequence badge (1, 2, 3, …) in the order
    /// they're declared (or per-edge `step` override), so a reader can trace the flow.
    #[serde(default)]
    pub numbered: Option<bool>,

    /// Named, reusable node style presets. A node opts in via `class: <name>`; any field the
    /// node doesn't already set explicitly is filled in from the preset. Existing keys are
    /// never overwritten by a preset — this exists to de-duplicate repeated per-node styling,
    /// not to act as a second source of truth.
    #[serde(default, alias = "node_classes", alias = "component_styles")]
    pub node_styles: HashMap<String, NodeStyleOverride>,

    /// Named, reusable edge style presets — same resolution rules as [`node_styles`].
    #[serde(default, alias = "edge_classes", alias = "connector_styles")]
    pub edge_styles: HashMap<String, EdgeStyleOverride>,

    /// Ordered list of node definitions (sequence diagrams: the participants, left to
    /// right).
    #[serde(default, alias = "participants")]
    pub nodes: Vec<NodeDef>,

    /// Ordered list of directed edge definitions.
    #[serde(default)]
    pub edges: Vec<EdgeDef>,

    /// Optional list of visual group / swimlane containers.
    #[serde(default, alias = "containers", alias = "swimlanes")]
    pub groups: Vec<GroupDef>,

    /// Sequence diagrams: the ordered script — messages, notes, fragments (alt / opt /
    /// loop / par / critical / break / region) and dividers. Setting it makes the
    /// diagram a sequence diagram. (Plain `edges` still work as a message list.)
    #[serde(default)]
    pub sequence: Vec<SeqStep>,
}

/// One step of a sequence diagram's script. Exactly one kind per step:
/// a message (`from` + `to`), a note (`note`), a fragment (`alt`, `opt`, `loop`, `par`,
/// `critical`, `break` or `region`, with nested `steps`) or a `divider`.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SeqStep {
    // -- message --------------------------------------------------------------------
    #[serde(default, alias = "source")]
    pub from: Option<String>,
    #[serde(default, alias = "target")]
    pub to: Option<String>,
    #[serde(default, alias = "text", alias = "message")]
    pub label: Option<String>,
    /// `flow` (sync call, default), `reply` / `return` (dashed), `async` (open head).
    #[serde(default, alias = "style")]
    pub edge_style: Option<String>,
    /// Start an activation bar on the receiver at this message (default: calls do,
    /// see `rdg --guide sequence`).
    #[serde(default)]
    pub activate: Option<bool>,
    /// End the sender's current activation at this message (default: replies do).
    #[serde(default)]
    pub deactivate: Option<bool>,
    /// The receiver is created by this message: its box appears here, not at the top.
    #[serde(default)]
    pub create: Option<bool>,
    /// The receiver is destroyed by this message: its lifeline ends with an ✕.
    #[serde(default)]
    pub destroy: Option<bool>,
    #[serde(default)]
    pub color: Option<String>,

    // -- note -------------------------------------------------------------------------
    /// Note text (`\n` for line breaks). Place it with `over`, `left_of` or `right_of`.
    #[serde(default)]
    pub note: Option<String>,
    /// Participant(s) the note spans: one id, or a list (spans first..last).
    #[serde(default, deserialize_with = "one_or_many")]
    pub over: Vec<String>,
    #[serde(default)]
    pub left_of: Option<String>,
    #[serde(default)]
    pub right_of: Option<String>,

    // -- fragments (the value is the guard/label, e.g. `alt: "valid token"`) ----------
    #[serde(default)]
    pub alt: Option<String>,
    #[serde(default)]
    pub opt: Option<String>,
    #[serde(default, rename = "loop")]
    pub loop_: Option<String>,
    #[serde(default)]
    pub par: Option<String>,
    #[serde(default)]
    pub critical: Option<String>,
    #[serde(default, rename = "break")]
    pub break_: Option<String>,
    /// A plain named box around steps (no special semantics).
    #[serde(default, alias = "group", alias = "box")]
    pub region: Option<String>,
    /// The fragment's (first) body.
    #[serde(default, alias = "do", alias = "then")]
    pub steps: Vec<SeqStep>,
    /// `alt` only: further branches, each `{label, steps}` (one mapping or a list).
    #[serde(default, rename = "else", deserialize_with = "one_or_many")]
    pub else_: Vec<SeqBranch>,
    /// `par` only: further parallel branches, each `{label, steps}`.
    #[serde(default, deserialize_with = "one_or_many")]
    pub and: Vec<SeqBranch>,

    // -- divider ----------------------------------------------------------------------
    /// A full-width separator with this label (phases, "5 minutes later", …).
    #[serde(default, alias = "separator", alias = "section")]
    pub divider: Option<String>,
}

/// A further branch of an `alt` (`else`) or `par` (`and`) fragment.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SeqBranch {
    #[serde(default, alias = "guard", alias = "condition")]
    pub label: Option<String>,
    #[serde(default, alias = "do", alias = "then")]
    pub steps: Vec<SeqStep>,
}

/// What a [`SeqStep`] is.
#[derive(Debug, Clone, PartialEq)]
pub enum SeqStepKind<'a> {
    Message { from: &'a str, to: &'a str },
    Note,
    /// `kind` is the fragment keyword (`alt`, `loop`, …), `label` its guard.
    Fragment { kind: &'static str, label: &'a str },
    Divider(&'a str),
}

impl SeqStep {
    /// The fragment keyword and guard this step sets, if any (all of them, so a step
    /// setting two can be reported).
    pub fn fragment_keys(&self) -> Vec<(&'static str, &str)> {
        [
            ("alt", &self.alt),
            ("opt", &self.opt),
            ("loop", &self.loop_),
            ("par", &self.par),
            ("critical", &self.critical),
            ("break", &self.break_),
            ("region", &self.region),
        ]
        .into_iter()
        .filter_map(|(k, v)| v.as_deref().map(|v| (k, v)))
        .collect()
    }

    /// Classify the step, or explain why it's ambiguous or empty.
    pub fn kind(&self) -> std::result::Result<SeqStepKind<'_>, String> {
        let frags = self.fragment_keys();
        let is_msg = self.from.is_some() || self.to.is_some();
        let kinds = usize::from(is_msg) + usize::from(self.note.is_some()) + usize::from(!frags.is_empty()) + usize::from(self.divider.is_some());
        if kinds == 0 {
            return Err("empty step: give `from`+`to` (message), `note`, a fragment (`alt`, `opt`, `loop`, `par`, `critical`, `break`, `region`) or `divider`".into());
        }
        if kinds > 1 || frags.len() > 1 {
            return Err("a step must be exactly one of: message (`from`+`to`), `note`, one fragment keyword, or `divider`".into());
        }
        if is_msg {
            return match (self.from.as_deref(), self.to.as_deref()) {
                (Some(f), Some(t)) => Ok(SeqStepKind::Message { from: f, to: t }),
                _ => Err("a message needs both `from` and `to`".into()),
            };
        }
        if self.note.is_some() {
            return Ok(SeqStepKind::Note);
        }
        if let Some(&(kind, label)) = frags.first() {
            return Ok(SeqStepKind::Fragment { kind, label });
        }
        Ok(SeqStepKind::Divider(self.divider.as_deref().unwrap_or_default()))
    }
}

/// A step label written as a number (`3`, and `3.1`, which YAML reads as a float) or a
/// string (`"3b"`), kept as the text the author wrote.
fn step_label<'de, D>(d: D) -> std::result::Result<Option<String>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Raw {
        Int(u64),
        Float(f64),
        Text(String),
    }
    Ok(match Option::<Raw>::deserialize(d)? {
        None => None,
        Some(Raw::Int(n)) => Some(n.to_string()),
        Some(Raw::Float(f)) => Some(f.to_string()),
        Some(Raw::Text(s)) => Some(s.trim().to_string()).filter(|s| !s.is_empty()),
    })
}

/// Why a step label is not usable, or `None` when it is: a number, optionally followed
/// by a branch (`3a`, `3b`, `3.1`, `3.1a`), at most 6 characters so it fits its badge.
pub fn step_label_problem(step: &str) -> Option<&'static str> {
    let digits = step.chars().take_while(char::is_ascii_digit).count();
    if digits == 0 {
        return Some("a step must start with a number, e.g. `3`, `3a` or `3.1`");
    }
    if step.chars().count() > 6 {
        return Some("a step label is at most 6 characters so it fits its badge");
    }
    if !step[digits..].chars().all(|c| c.is_ascii_alphanumeric() || c == '.') {
        return Some("a step is a number with an optional branch, e.g. `3a` or `3.1`");
    }
    None
}

/// The leading number of a step label (`"12b"` → 12).
pub fn step_major(step: &str) -> Option<u32> {
    let digits: String = step.chars().take_while(char::is_ascii_digit).collect();
    digits.parse().ok()
}

/// The badge text for each edge, in declaration order. An explicit `step` is used as
/// written; an edge without one takes the number after the previous edge's (so after
/// `3a`, `3b` comes `4`). Without `numbered: true` only explicit steps are shown.
pub fn resolve_steps(edges: &[EdgeDef], numbered: bool) -> Vec<Option<String>> {
    let mut last = 0u32;
    edges
        .iter()
        .map(|e| match e.step.as_deref() {
            Some(s) => {
                last = step_major(s).unwrap_or(last);
                Some(s.to_string())
            }
            None if numbered => {
                last += 1;
                Some(last.to_string())
            }
            None => None,
        })
        .collect()
}

/// Accepts one value or a list of them.
fn one_or_many<'de, D, T>(d: D) -> std::result::Result<Vec<T>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: serde::Deserialize<'de>,
{
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum OneOrMany<T> {
        Many(Vec<T>),
        One(T),
    }
    Ok(match OneOrMany::<T>::deserialize(d)? {
        OneOrMany::Many(v) => v,
        OneOrMany::One(x) => vec![x],
    })
}

/// Overall flow direction of the diagram, as resolved from the YAML payload.
///
/// Deliberately schema-local (rather than reusing `rdg_layout::LayoutDirection`) so that
/// `rdg-schema` has no dependency on `rdg-layout`; the CLI maps this to the layout
/// engine's own direction type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Direction {
    /// Top to Bottom (hierarchical DAG standard).
    TopToBottom,
    /// Left to Right (horizontal pipelines, sequence flows).
    LeftToRight,
}

fn default_diagram_type() -> String {
    "flowchart".to_owned()
}

fn default_node_type() -> String {
    "default".to_owned()
}

/// Rewrites serde's "unknown field `x`, expected one of `a`, `b`, … at line L column C"
/// into a short "did you mean" when one expected field is close — an LLM's typo
/// (`lable`, `langauge`) is almost always one or two edits from the real name, and the
/// fix is more useful up front than a 50-name list of every alias.
fn unknown_field_hint(msg: &str) -> Option<String> {
    let (prefix, rest) = msg.split_once("unknown field `")?;
    let (field, rest) = rest.split_once('`')?;
    let expected: Vec<&str> = rest.split('`').skip(1).step_by(2).collect();
    let best = closest_match(field, expected.iter().copied())?;
    let location = rest.rfind(" at line ").map_or(String::new(), |i| format!(" ({})", rest[i + 1..].trim()));
    Some(format!("{prefix}unknown field `{field}`{location} — did you mean `{best}`?"))
}

/// The candidate closest to `word` by edit distance, if it's close enough to plausibly
/// be what was meant (at most a third of the word's length, minimum 2 edits).
pub fn closest_match<'a>(word: &str, candidates: impl IntoIterator<Item = &'a str>) -> Option<&'a str> {
    let w = word.to_ascii_lowercase();
    let limit = (w.chars().count() / 3).max(2);
    candidates
        .into_iter()
        .map(|c| (edit_distance(&w, &c.to_ascii_lowercase()), c))
        .filter(|&(d, _)| d <= limit)
        .min_by_key(|&(d, c)| (d, c.len()))
        .map(|(_, c)| c)
}

/// Levenshtein distance, counting an adjacent transposition as one edit.
fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut d = vec![vec![0usize; b.len() + 1]; a.len() + 1];
    for (i, row) in d.iter_mut().enumerate() {
        row[0] = i;
    }
    for (j, cell) in d[0].iter_mut().enumerate() {
        *cell = j;
    }
    for i in 1..=a.len() {
        for j in 1..=b.len() {
            let cost = usize::from(a[i - 1] != b[j - 1]);
            d[i][j] = (d[i - 1][j] + 1).min(d[i][j - 1] + 1).min(d[i - 1][j - 1] + cost);
            if i > 1 && j > 1 && a[i - 1] == b[j - 2] && a[i - 2] == b[j - 1] {
                d[i][j] = d[i][j].min(d[i - 2][j - 2] + 1);
            }
        }
    }
    d[a.len()][b.len()]
}

impl DiagramPayload {
    /// Parse a YAML string into a [`DiagramPayload`].
    ///
    /// # Errors
    ///
    /// Returns an error if the YAML is malformed or cannot be parsed.
    pub fn from_yaml(input: &str) -> Result<Self> {
        serde_yaml::from_str(input).map_err(|e| {
            let msg = e.to_string();
            anyhow::anyhow!(unknown_field_hint(&msg).unwrap_or(msg))
                .context("failed to deserialize YAML diagram payload")
        })
    }

    /// Resolves the optional direction string into a [`Direction`].
    ///
    /// This is a schema-local type (rather than `rdg_layout::LayoutDirection`) so that
    /// `rdg-schema` does not need to depend on `rdg-layout`; callers map it to the
    /// layout engine's own direction type.
    pub fn resolved_direction(&self) -> Option<Direction> {
        self.direction
            .as_deref()
            .map(|d| match d.trim().to_ascii_lowercase().as_str() {
                "lr" | "left_to_right" | "horizontal" | "h" => Direction::LeftToRight,
                _ => Direction::TopToBottom,
            })
    }

    /// Returns the resolved canonical diagram category.
    /// Values: `"flowchart"`, `"architecture"`, `"sequence"`, `"er"`, `"class"`, `"state"`.
    pub fn resolved_diagram_type(&self) -> &str {
        if !self.sequence.is_empty() {
            return "sequence";
        }
        match self.diagram_type.to_ascii_lowercase().trim() {
            "seq" | "sequence" | "uml_sequence" => "sequence",
            "er" | "erd" | "database" | "schema" | "relational" => "er",
            "class" | "uml_class" | "oop" => "class",
            "state" | "state_machine" | "fsm" => "state",
            "arch" | "architecture" | "system" => "architecture",
            _ => "flowchart",
        }
    }

    /// Returns `true` when edges should be annotated with a flow sequence badge.
    pub fn is_numbered(&self) -> bool {
        self.numbered.unwrap_or(false)
    }

    /// Merges a node's `class` style preset (if any) into a copy of `node`.
    ///
    /// Fields the node already set explicitly are left untouched — a preset only fills in
    /// gaps, it never overrides an author's explicit choice. Unknown class names, or a node
    /// with no `class`, return `node` unchanged (cloned).
    pub fn effective_node(&self, node: &NodeDef) -> NodeDef {
        let mut merged = node.clone();
        let Some(class) = node.class.as_deref() else {
            return merged;
        };
        let Some(preset) = self.node_styles.get(class) else {
            return merged;
        };
        if merged.color.is_none() {
            merged.color = preset.color.clone();
        }
        if merged.technology.is_none() {
            merged.technology = preset.technology.clone();
        }
        if merged.language.is_none() {
            merged.language = preset.language.clone();
        }
        if merged.db_type.is_none() {
            merged.db_type = preset.db_type.clone();
        }
        if merged.icon.is_none() {
            merged.icon = preset.icon.clone();
        }
        if merged.category.is_none() {
            merged.category = preset.category.clone();
        }
        if merged.width.is_none() {
            merged.width = preset.width;
        }
        if merged.height.is_none() {
            merged.height = preset.height;
        }
        if merged.provider.is_none() {
            merged.provider = preset.provider.clone();
        }
        if merged.style_extra.is_none() {
            merged.style_extra = preset.style_extra.clone();
        }
        merged
    }

    /// Merges an edge's `class` style preset (if any) into a copy of `edge`. Same
    /// gap-filling semantics as [`DiagramPayload::effective_node`].
    pub fn effective_edge(&self, edge: &EdgeDef) -> EdgeDef {
        let mut merged = edge.clone();
        let Some(class) = edge.class.as_deref() else {
            return merged;
        };
        let Some(preset) = self.edge_styles.get(class) else {
            return merged;
        };
        if merged.edge_style.is_none() {
            merged.edge_style = preset.edge_style.clone();
        }
        if merged.color.is_none() {
            merged.color = preset.color.clone();
        }
        if merged.width.is_none() {
            merged.width = preset.width;
        }
        if merged.line_style.is_none() {
            merged.line_style = preset.line_style.clone();
        }
        if merged.head.is_none() {
            merged.head = preset.head.clone();
        }
        if merged.tail.is_none() {
            merged.tail = preset.tail.clone();
        }
        if merged.style_extra.is_none() {
            merged.style_extra = preset.style_extra.clone();
        }
        merged
    }

    /// Returns a complete, production-ready reference YAML template.
    pub fn example_yaml() -> &'static str {
        EXAMPLE_YAML
    }

    /// Returns the JSON Schema (draft-07) specification for [`DiagramPayload`].
    pub fn json_schema() -> &'static str {
        JSON_SCHEMA
    }
}

impl Default for DiagramPayload {
    fn default() -> Self {
        Self {
            title: None,
            description: None,
            diagram_type: default_diagram_type(),
            theme: None,
            direction: None,
            rank_spacing: None,
            node_spacing: None,
            canvas: None,
            spacing: None,
            numbered: None,
            legend: None,
            node_styles: HashMap::new(),
            edge_styles: HashMap::new(),
            nodes: Vec::new(),
            edges: Vec::new(),
            groups: Vec::new(),
            sequence: Vec::new(),
        }
    }
}

// ---------------------------------------------------------------------------
// Canvas & spacing configuration
// ---------------------------------------------------------------------------

/// Canvas-level rendering configuration.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CanvasConfig {
    /// Outer margin in pixels around the whole diagram (replaces the built-in default).
    #[serde(default)]
    pub margin: Option<f64>,

    /// Canvas background color (e.g. `#f8fafc`). Overrides the theme default.
    #[serde(default, alias = "bg", alias = "fill")]
    pub background: Option<String>,
}

/// Grouped spacing configuration — an alternative to the flat `rank_spacing`/`node_spacing`
/// top-level fields for payloads that want every spacing knob in one place.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SpacingConfig {
    /// Vertical gap between ranks/layers in pixels.
    #[serde(default)]
    pub rank: Option<u32>,

    /// Horizontal gap between sibling nodes on the same rank in pixels.
    #[serde(default)]
    pub node: Option<u32>,

    /// Horizontal gap between adjacent group containers in pixels.
    #[serde(default)]
    pub group_gap_x: Option<f64>,

    /// Vertical gap between adjacent group containers in pixels.
    #[serde(default)]
    pub group_gap_y: Option<f64>,
}

// ---------------------------------------------------------------------------
// Group / Swimlane definition
// ---------------------------------------------------------------------------

/// Visual container grouping a set of related nodes.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GroupDef {
    /// Unique identifier for the group container.
    pub id: String,

    /// Label displayed in the group header.
    #[serde(alias = "title", alias = "name")]
    pub label: String,

    /// Optional accent color for container background/border (e.g. `#0284c7`).
    #[serde(default, alias = "border", alias = "fill", alias = "accent")]
    pub color: Option<String>,

    /// Members: node ids, and ids of groups nested inside this one.
    #[serde(default, alias = "members", alias = "node_ids")]
    pub nodes: Vec<String>,

    /// Id of the group this one is drawn inside (same as listing this group's id in the
    /// parent's `nodes`).
    #[serde(default, alias = "in", alias = "inside")]
    pub parent: Option<String>,

    /// Optional programming language or tech stack for the container (e.g. `rust`, `go`, `python`).
    /// When specified or detected, member nodes sharing this stack do not display redundant icons.
    #[serde(default, alias = "lang")]
    pub language: Option<String>,

    /// Semantic category (colour) of the container: `backend`, `database`, `cloud`, …
    #[serde(default)]
    pub category: Option<String>,

    /// Optional explicit brand or service icon for the group container header.
    #[serde(default)]
    pub icon: Option<String>,
}

impl GroupDef {
    /// Resolves the programming language for this container.
    pub fn resolved_language(&self) -> Option<String> {
        let explicit =
            rdg_icons::detect_language(self.language.as_deref(), None, &self.label, None);
        if explicit.is_some() {
            return explicit.map(|s| s.to_string());
        }
        // Check for common prefix patterns like "crates/" or "cargo/"
        let lower = self.label.to_ascii_lowercase();
        if lower.contains("crates/") || lower.contains("cargo") {
            return Some("rust".to_string());
        }
        None
    }

    /// Resolves the icon key for the container header.
    pub fn resolved_icon(&self) -> Option<String> {
        if let Some(i) = &self.icon {
            if !i.trim().is_empty() {
                return Some(i.trim().to_ascii_lowercase());
            }
        }
        if let Some(l) = self.resolved_language() {
            return Some(l);
        }
        None
    }
}

/// How the groups nest and which nodes each one holds directly, resolved once from the
/// YAML (see [`DiagramPayload::group_tree`]) so validation, layout and rendering agree.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct GroupTree {
    /// Enclosing group of each group (indices into `groups`); `None` at the top level.
    pub parent: Vec<Option<usize>>,
    /// Node ids each group holds *directly* — a node listed by a group and by a group
    /// nested in it belongs to the inner one.
    pub nodes: Vec<Vec<String>>,
    /// Structural problems met while resolving (unknown members are left to the caller).
    pub issues: Vec<GroupIssue>,
}

/// A problem in how groups are declared.
#[derive(Debug, Clone, PartialEq)]
pub struct GroupIssue {
    /// Blocks rendering (else it's a warning).
    pub error: bool,
    /// YAML location, e.g. `groups[2].parent`.
    pub path: String,
    pub message: String,
}

impl GroupTree {
    /// Groups directly inside group `g`, in declaration order.
    pub fn children(&self, g: usize) -> impl Iterator<Item = usize> + '_ {
        (0..self.parent.len()).filter(move |&c| self.parent[c] == Some(g))
    }

    /// Nesting depth of group `g` (0 at the top level).
    pub fn depth(&self, g: usize) -> usize {
        std::iter::successors(self.parent[g], |&p| self.parent[p]).count()
    }

    /// Whether `a` is `b` or encloses it (at any depth).
    pub fn contains(&self, a: usize, b: usize) -> bool {
        std::iter::successors(Some(b), |&p| self.parent[p]).any(|g| g == a)
    }

    /// Every group, each one before the groups nested in it (declaration order among
    /// siblings) — the order containers are drawn in, so inner boxes land on top.
    pub fn outer_first(&self) -> Vec<usize> {
        let mut out = Vec::with_capacity(self.parent.len());
        let mut stack: Vec<usize> = (0..self.parent.len()).filter(|&g| self.parent[g].is_none()).rev().collect();
        while let Some(g) = stack.pop() {
            out.push(g);
            let kids: Vec<usize> = self.children(g).collect();
            stack.extend(kids.into_iter().rev());
        }
        out
    }
}

impl DiagramPayload {
    /// Resolves group nesting and direct membership.
    ///
    /// A group is nested by naming its parent (`parent: outer`) or by listing its id in
    /// the parent's `nodes`. A group that declares neither is placed inside the smallest
    /// other group whose nodes include all of its own — how a writer who lists a node in
    /// both an outer and an inner group means it. A node listed by groups that don't nest
    /// stays in the first one (a warning).
    pub fn group_tree(&self) -> GroupTree {
        let n = self.groups.len();
        let mut issues = Vec::new();
        let mut index: HashMap<&str, usize> = HashMap::new();
        for (i, g) in self.groups.iter().enumerate() {
            index.entry(g.id.as_str()).or_insert(i);
        }
        let node_ids: std::collections::HashSet<&str> = self.nodes.iter().map(|n| n.id.as_str()).collect();

        // --- Declared nesting: `parent:`, or a group id among another group's members ---
        let mut parent: Vec<Option<usize>> = vec![None; n];
        let mut declared_at: Vec<Option<String>> = vec![None; n];
        let mut declare = |child: usize, p: usize, path: String, issues: &mut Vec<GroupIssue>| {
            if child == p {
                issues.push(GroupIssue { error: true, path, message: format!("group `{}` cannot contain itself", self.groups[child].id) });
            } else if let Some(prev) = parent[child].filter(|&q| q != p) {
                issues.push(GroupIssue {
                    error: true,
                    path,
                    message: format!(
                        "group `{}` is already inside `{}` ({}); a group has one parent",
                        self.groups[child].id,
                        self.groups[prev].id,
                        declared_at[child].as_deref().unwrap_or("?")
                    ),
                });
            } else {
                parent[child] = Some(p);
                declared_at[child] = Some(path);
            }
        };
        for (i, g) in self.groups.iter().enumerate() {
            if let Some(p) = g.parent.as_deref() {
                match index.get(p) {
                    Some(&pi) => declare(i, pi, format!("groups[{i}].parent"), &mut issues),
                    None => issues.push(GroupIssue {
                        error: true,
                        path: format!("groups[{i}].parent"),
                        message: format!("unknown group id `{p}`"),
                    }),
                }
            }
        }
        for (i, g) in self.groups.iter().enumerate() {
            for (j, m) in g.nodes.iter().enumerate() {
                if let (Some(&c), false) = (index.get(m.as_str()), node_ids.contains(m.as_str())) {
                    declare(c, i, format!("groups[{i}].nodes[{j}]"), &mut issues);
                }
            }
        }
        // A cycle (a inside b inside a) is cut where it closes.
        for g in 0..n {
            let mut seen = vec![false; n];
            let mut cur = g;
            while let Some(p) = parent[cur] {
                if seen[p] {
                    issues.push(GroupIssue {
                        error: true,
                        path: declared_at[cur].clone().unwrap_or_else(|| format!("groups[{cur}]")),
                        message: format!("groups `{}` and `{}` are nested inside each other", self.groups[cur].id, self.groups[p].id),
                    });
                    parent[cur] = None;
                    break;
                }
                seen[p] = true;
                cur = p;
            }
        }

        // --- Implied nesting: all of a group's nodes are listed by a bigger group --------
        let listed = |g: usize| -> std::collections::HashSet<&str> {
            self.groups[g].nodes.iter().map(String::as_str).filter(|m| node_ids.contains(m)).collect()
        };
        let own: Vec<_> = (0..n).map(listed).collect();
        let tree = |parent: &[Option<usize>]| GroupTree { parent: parent.to_vec(), ..Default::default() };
        let all_nodes = |parent: &[Option<usize>], g: usize| -> std::collections::HashSet<&str> {
            let t = tree(parent);
            (0..n).filter(|&d| t.contains(g, d)).flat_map(|d| own[d].iter().copied()).collect()
        };
        let declared = parent.clone();
        for g in 0..n {
            if declared[g].is_some() || index.get(self.groups[g].id.as_str()) != Some(&g) {
                continue;
            }
            let mine = all_nodes(&declared, g);
            if mine.is_empty() {
                continue;
            }
            let t = tree(&declared);
            parent[g] = (0..n)
                .filter(|&o| o != g && !t.contains(g, o))
                .map(|o| (o, all_nodes(&declared, o)))
                .filter(|(_, theirs)| theirs.len() > mine.len() && mine.is_subset(theirs))
                .min_by_key(|(o, theirs)| (theirs.len(), *o))
                .map(|(o, _)| o);
        }

        // --- Direct membership: the innermost of the groups listing a node ------------
        let t = tree(&parent);
        let mut home: HashMap<&str, usize> = HashMap::new();
        for (i, g) in self.groups.iter().enumerate() {
            for (j, m) in g.nodes.iter().enumerate() {
                if !node_ids.contains(m.as_str()) {
                    continue;
                }
                match home.get(m.as_str()).copied() {
                    None => {
                        home.insert(m, i);
                    }
                    Some(h) if t.contains(h, i) => {
                        home.insert(m, i);
                    }
                    Some(h) if t.contains(i, h) => {}
                    Some(h) => issues.push(GroupIssue {
                        error: false,
                        path: format!("groups[{i}].nodes[{j}]"),
                        message: format!(
                            "node `{m}` is also in group `{}`, which is not nested with `{}`; it stays in `{}`",
                            self.groups[h].id, g.id, self.groups[h].id
                        ),
                    }),
                }
            }
        }
        let mut nodes = vec![Vec::new(); n];
        for (i, g) in self.groups.iter().enumerate() {
            for m in &g.nodes {
                if home.get(m.as_str()) == Some(&i) && !nodes[i].contains(m) {
                    nodes[i].push(m.clone());
                }
            }
        }
        GroupTree { parent, nodes, issues }
    }
}

