/// A directed edge between two nodes.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct EdgeDef {
    /// Source node ID.
    #[serde(alias = "source", alias = "src")]
    pub from: String,

    /// Target node ID.
    #[serde(alias = "target", alias = "dst")]
    pub to: String,

    /// Optional label rendered along the connector.
    #[serde(default, alias = "name", alias = "text")]
    pub label: Option<String>,

    /// Optional semantic edge style: `flow`, `async`, `error`, `data`, `bidirectional`,
    /// `sync`, `reply`, `self`, `one_to_many`, `many_to_many`, `one_to_one`, `zero_to_many`,
    /// `inheritance`, `composition`, `aggregation`, `realization`, `dependency`.
    #[serde(default, alias = "style", alias = "type")]
    pub edge_style: Option<String>,

    /// Optional flag to render bidirectional arrows.
    #[serde(default, alias = "bidir")]
    pub bidirectional: Option<bool>,

    /// Optional stroke color for the edge connector (e.g. `#ef4444`, `#0284c7`).
    #[serde(default, alias = "colour", alias = "stroke")]
    pub color: Option<String>,

    /// Optional stroke width/thickness in pixels (e.g. 1.5, 2.0).
    #[serde(default, alias = "stroke_width", alias = "thickness")]
    pub width: Option<f64>,

    /// Optional line style: `solid`, `dashed`, `dotted`.
    #[serde(
        default,
        alias = "stroke_style",
        alias = "pattern",
        alias = "style_type"
    )]
    pub line_style: Option<String>,

    /// Optional arrow head marker type: `classic`, `block`, `blockThin`, `open`, `diamond`, `oval`, `none`, `ERmany`, `ERone`, etc.
    #[serde(
        default,
        alias = "arrow_head",
        alias = "end_arrow",
        alias = "head_type",
        alias = "target_arrow"
    )]
    pub head: Option<String>,

    /// Optional arrow tail marker type: `none`, `diamond`, `oval`, `ERone`, `open`, etc.
    #[serde(
        default,
        alias = "arrow_tail",
        alias = "start_arrow",
        alias = "tail_type",
        alias = "source_arrow"
    )]
    pub tail: Option<String>,

    /// Optional explicit source port face: `top`, `bottom`, `left`, `right`.
    #[serde(default, alias = "src_port", alias = "from_port", alias = "exit_port")]
    pub source_port: Option<String>,

    /// Optional explicit target port face: `top`, `bottom`, `left`, `right`.
    #[serde(default, alias = "dst_port", alias = "to_port", alias = "entry_port")]
    pub target_port: Option<String>,

    /// Explicit flow step shown in the edge's badge: a number (`3`) or a branch of one
    /// (`3a`, `3b`, `3.1`). Edges without one continue from the previous step when the
    /// diagram sets `numbered: true` (see [`resolve_steps`]).
    #[serde(default, alias = "order", alias = "sequence", deserialize_with = "step_label")]
    pub step: Option<String>,

    /// Optional named style preset to inherit from — see [`DiagramPayload::edge_styles`].
    #[serde(default, alias = "preset")]
    pub class: Option<String>,

    /// Optional raw draw.io style fragment appended verbatim to the computed edge style
    /// string. draw.io-only, same as [`NodeDef::style_extra`].
    #[serde(default, alias = "drawio_style", alias = "extra_style")]
    pub style_extra: Option<String>,
}

impl EdgeDef {
    /// Resolves the effective semantic edge style.
    pub fn resolved_style(&self) -> Option<String> {
        if self.bidirectional == Some(true) {
            return Some("bidirectional".to_string());
        }
        self.edge_style
            .as_deref()
            .map(|s| match s.to_ascii_lowercase().trim() {
                "sync" | "call" | "sync_call" => "sync".to_string(),
                "reply" | "return" | "response" => "reply".to_string(),
                "self" | "self_call" => "self".to_string(),
                "1..*" | "1:n" | "one_to_many" => "one_to_many".to_string(),
                "*..*" | "m:n" | "many_to_many" => "many_to_many".to_string(),
                "1..1" | "1:1" | "one_to_one" => "one_to_one".to_string(),
                "0..*" | "0:n" | "zero_to_many" => "zero_to_many".to_string(),
                "inheritance" | "extends" | "is_a" => "inheritance".to_string(),
                "realization" | "implements" => "realization".to_string(),
                "composition" => "composition".to_string(),
                "aggregation" => "aggregation".to_string(),
                "dependency" => "dependency".to_string(),
                other => other.to_string(),
            })
    }
}

